WITH profile_pairs AS (
    SELECT DISTINCT {{left_entity_columns}}, {{right_entity_columns}}
    FROM (
        {{entity_pair_query}}
    ) e
    WHERE ({{entity_pair_eligibility_condition}})
),
profile_left_degrees AS (
    SELECT COUNT(*) AS profile_degree
    FROM profile_pairs e
    GROUP BY {{left_entity_columns}}
),
profile_right_degrees AS (
    SELECT COUNT(*) AS profile_degree
    FROM profile_pairs e
    GROUP BY {{right_entity_columns}}
),
profile_summary AS (
    SELECT (SELECT COUNT(*) FROM profile_pairs) AS profile_pair_count,
           l.profile_left_entity_count,
           r.profile_right_entity_count,
           l.profile_max_rights_per_left,
           r.profile_max_lefts_per_right
    FROM (
        SELECT COUNT(*) AS profile_left_entity_count,
               MAX(profile_degree) AS profile_max_rights_per_left
        FROM profile_left_degrees
    ) l
    CROSS JOIN (
        SELECT COUNT(*) AS profile_right_entity_count,
               MAX(profile_degree) AS profile_max_lefts_per_right
        FROM profile_right_degrees
    ) r
)
SELECT p.*
FROM profile_summary p
WHERE p.profile_pair_count > 0
  AND [[test]];

WITH profile_counts AS (
    SELECT {{category_columns}}, COUNT(*) AS profile_count
    FROM {{schema_name}}.{{table_name}} t
    WHERE ({{population_scope_condition}}) AND ({{category_nonnull_condition}})
    GROUP BY {{category_columns}}
), profile_shares AS (
    SELECT 1.0 * profile_count / NULLIF(SUM(profile_count) OVER (), 0) AS profile_probability,
           SUM(profile_count) OVER () AS profile_population_count
    FROM profile_counts
), profile_entropy AS (
    SELECT -SUM(profile_probability * LN(profile_probability)) /
           NULLIF(LN(CASE WHEN {{log_base}} > 1 AND {{log_base}} <= 1e60
                          THEN {{log_base}} END), 0) AS profile_entropy,
           MAX(profile_population_count) AS profile_population_count
    FROM profile_shares
)
SELECT p.* FROM profile_entropy p
WHERE p.profile_population_count >= {{minimum_sample_size}} AND {{minimum_sample_size}} >= 1
  AND {{entropy_lower}} >= 0 AND {{entropy_upper}} >= {{entropy_lower}}
  AND [[test]];

WITH profile_old AS (
    {{old_metadata_query}}
), profile_new AS (
    {{new_metadata_query}}
), profile_old_only AS (
    SELECT {{metadata_columns}} FROM profile_old
    MINUS
    SELECT {{metadata_columns}} FROM profile_new
), profile_new_only AS (
    SELECT {{metadata_columns}} FROM profile_new
    MINUS
    SELECT {{metadata_columns}} FROM profile_old
), profile_counts AS (
    SELECT (SELECT COUNT(*) FROM profile_old_only) AS profile_old_only_count,
           (SELECT COUNT(*) FROM profile_new_only) AS profile_new_only_count
    FROM DUAL
)
SELECT p.* FROM profile_counts p
WHERE ({{snapshot_scope_known_condition}})
  AND [[test]];
